input.old_string:
static void update_home_suggestion_preview(void)
{
  struct home_proactive_snapshot_s snapshot;
  const char *title;
  char reason[160];

  if (g_home_suggestion_title == NULL ||
      g_home_suggestion_reason == NULL)
    {
      return;
    }

  home_proactive_get_snapshot(&snapshot);
  if (snapshot.suggestion_available)
    {
      title = snapshot.candidate_kind ==
                HOME_PROACTIVE_CANDIDATE_EVENT_ROUTINE ?
                "发现设备联动建议" :
              snapshot.candidate_kind ==
                HOME_PROACTIVE_CANDIDATE_TIME_ROUTINE ?
                "发现时间习惯建议" : "你可能准备休息了";
      snprintf(reason, sizeof(reason),
               "依据 %u 次观察 · 置信度 %u%%%s%s",
               snapshot.candidate_observations, snapshot.confidence,
               snapshot.target_name[0] != '\0' ? " · 目标 " : "",
               snapshot.target_name);
    }
  else
    {
      title = snapshot.clock_valid ? "正在学习家庭习惯" :
                                     "等待时间与设备状态";
      snprintf(reason, sizeof(reason),
               snapshot.profile_learned || snapshot.routine_count > 0 ?
                 "已学习 %u 条习惯，达到阈值后会先征求你的确认" :
                 "设备状态与反馈会在本地持续形成建议",
               snapshot.routine_count);
    }

  set_label_text_if_changed(g_home_suggestion_title, title);
  set_label_text_if_changed(g_home_suggestion_reason, reason);
  if (g_home_suggestion_execute != NULL)
    {
      if (snapshot.suggestion_available)
        {
          lv_obj_remove_flag(g_home_suggestion_execute,
                             LV_OBJ_FLAG_HIDDEN);
          lv_obj_remove_flag(g_home_suggestion_ignore,
                             LV_OBJ_FLAG_HIDDEN);
        }
      else
        {
          lv_obj_add_flag(g_home_suggestion_execute, LV_OBJ_FLAG_HIDDEN);
          lv_obj_add_flag(g_home_suggestion_ignore, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

