static const char *control_display_name(const char *name)
{
  if (strcmp(name, "on") == 0)
    {
      return "电源";
    }
  if (strcmp(name, "brightness") == 0)
    {
      return "亮度";
    }
  if (strcmp(name, "volume") == 0)
    {
      return "音量";
    }
  if (strcmp(name, "mute") == 0)
