      return "静音";
    }
  if (strcmp(name, "microphone-mute") == 0)
    {
      return "麦克风静音";
    }
  if (strcmp(name, "target-temperature") == 0)
    {
      return "目标温度";
    }
  if (strcmp(name, "color-temperature") == 0)
    {
      return "色温";
    }
  if (strcmp(name, "physical-controls-locked") == 0)
    {
      return "童锁";
    }
  if (strcmp(name, "indicator-light-on") == 0)
    {
      return "指示灯";
    }
  if (strcmp(name, "alarm") == 0)
