+  if (property->type == HOME_PANEL_CONTROL_BOOLEAN)
+    {
+      /* Boolean: status text + toggle */
+
+      value_label = home_ui_make_label(row,
+                               property->has_value ?
+                                 (property->boolean_value ? "已开启" :
+                                                            "已关闭") :
+                                 "状态未知",
+                               0, 32, lv_color_hex(COLOR_SECONDARY),
