static void proactive_automation_delete_clicked(lv_event_t *event)
{
  struct proactive_automation_ui_s *binding =
    lv_event_get_user_data(event);
  int ret;

  if (binding == NULL || binding->routine_id == 0)
    {
      return;
    }

  if (binding->cloud)
    {
      unsigned int index;

      ret = -ENOENT;
      for (index = 0; index < g_cloud_automation_count; index++)
        {
          if (g_cloud_automations[index].routine_id == binding->routine_id)
            {
              g_cloud_automation_count--;
              if (index < g_cloud_automation_count)
                {
                  memmove(&g_cloud_automations[index],
                          &g_cloud_automations[index + 1],
                          sizeof(g_cloud_automations[0]) *
                            (g_cloud_automation_count - index));
                  memmove(&g_cloud_due_at[index],
                          &g_cloud_due_at[index + 1],
                          sizeof(g_cloud_due_at[0]) *
                            (g_cloud_automation_count - index));
                }
              memset(&g_cloud_automations[g_cloud_automation_count], 0,
                     sizeof(g_cloud_automations[0]));
              g_cloud_due_at[g_cloud_automation_count] = 0;
              ret = 0;
              break;
            }
        }
    }
  else
    {
      ret = home_proactive_remove_automation(binding->routine_id);
    }
  if (ret == 0)
    {
      schedule_proactive_persist();
      set_label_text_if_changed(g_proactive_feedback_label,
                                "离线自动化已删除并停止执行");
      g_proactive_automation_signature = 0;
      update_proactive_widgets();
    }
  else
    {
      set_label_text_if_changed(g_proactive_feedback_label,
                                "自动化已不存在，无需重复删除");
    }
}

static void proactive_confirm_close(lv_event_t *event)
{
  lv_obj_t *shade = lv_event_get_user_data(event);

  if (shade != NULL && shade == g_proactive_confirm_shade)
    {
      g_proactive_confirm_shade = NULL;
      g_proactive_confirm_key = 0;
      lv_obj_delete(shade);
    }
}

static void proactive_confirm_accept(lv_event_t *event)
{
  struct home_proactive_snapshot_s snapshot;
  lv_obj_t *shade = lv_event_get_user_data(event);
  uint32_t expected_key = g_proactive_confirm_key;

  if (shade == NULL || shade != g_proactive_confirm_shade)
    {
      return;
    }

  g_proactive_confirm_shade = NULL;
  g_proactive_confirm_key = 0;
  lv_obj_delete(shade);

  home_proactive_get_snapshot(&snapshot);
  if (!snapshot.suggestion_available ||
      snapshot.decision_key != expected_key)
    {
      set_label_text_if_changed(g_proactive_feedback_label,
                                "建议已发生变化，请重新确认");
      update_proactive_widgets();
      return;
    }

  proactive_handle_feedback(HOME_PROACTIVE_ENABLE_AUTOMATION, true);
}

static void proactive_show_automation_confirm(
  const struct home_proactive_snapshot_s *snapshot)
{
  lv_obj_t *dialog;
  lv_obj_t *label;
  lv_obj_t *button;
  char detail[192];

  if (snapshot == NULL || g_proactive_confirm_shade != NULL)
    {
      return;
    }

  g_proactive_confirm_shade = component_create_dialog(
    NULL, 560, 286, "建立离线自动化？");
  if (g_proactive_confirm_shade == NULL)
    {
      return;
    }

  g_proactive_confirm_key = snapshot->decision_key;
  dialog = lv_obj_get_child(g_proactive_confirm_shade, 0);
  if (dialog == NULL)
    {
      component_close_dialog(g_proactive_confirm_shade);
      g_proactive_confirm_shade = NULL;
      g_proactive_confirm_key = 0;
      return;
    }

  snprintf(detail, sizeof(detail),
           "确认后，本建议会写入开发板并可在断网时自动执行。\n"
           "目标：%s\n可随时在"主动智能"页面删除。",
           snapshot->target_name[0] != '\0' ? snapshot->target_name :
                                               "当前建议设备");
  label = make_label(dialog, detail, 20, 70,
                     lv_color_hex(COLOR_SECONDARY),
                     home_panel_font_get());
  lv_obj_set_width(label, 472);
  lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
  lv_obj_set_style_text_line_space(label, 8, 0);

  button = make_action_button(dialog, "取消", 196, 186, 136);
  style_secondary_action(button);
  lv_obj_remove_event_cb(button, action_clicked);
  lv_obj_add_event_cb(button, proactive_confirm_close,
                      LV_EVENT_CLICKED, g_proactive_confirm_shade);

  button = make_action_button(dialog, "确认并启用", 348, 186, 164);
  lv_obj_remove_event_cb(button, action_clicked);
  lv_obj_add_event_cb(button, proactive_confirm_accept,
                      LV_EVENT_CLICKED, g_proactive_confirm_shade);
}

static uint32_t proactive_automation_signature(
  const struct home_proactive_automation_s *items,
  unsigned int count)
{
  uint32_t hash = 2166136261u;
  unsigned int index;

  for (index = 0; index < count; index++)
    {
      hash = (hash ^ items[index].routine_id) * 16777619u;
      hash = (hash ^ items[index].trigger_device_hash) * 16777619u;
      hash = (hash ^ items[index].action_device_hash) * 16777619u;
      hash = (hash ^ items[index].action_siid) * 16777619u;
      hash = (hash ^ items[index].action_piid) * 16777619u;
      hash = (hash ^ items[index].mean_minute_of_day) * 16777619u;
      hash = (hash ^ items[index].mean_delay_seconds) * 16777619u;
      hash = (hash ^ items[index].action_kind) * 16777619u;
      hash = (hash ^ (items[index].event_triggered ? 1u : 0u)) *
             16777619u;
      hash = (hash ^ (uint32_t)items[index].action_value) * 16777619u;
    }
  return (hash ^ count) == 0 ? 1 : (hash ^ count);
}

static void update_proactive_automation_list(void)
{
  struct home_proactive_automation_s
    items[HOME_PROACTIVE_MAX_AUTOMATIONS];
  unsigned int count;
  unsigned int index;
  uint32_t signature;

  if (g_proactive_automation_list == NULL)
    {
      return;
    }

  memset(items, 0, sizeof(items));
  count = home_proactive_list_automations(
    items, HOME_PROACTIVE_MAX_AUTOMATIONS);
  if (count > HOME_PROACTIVE_MAX_AUTOMATIONS)
    {
      count = HOME_PROACTIVE_MAX_AUTOMATIONS;
    }
  signature = proactive_automation_signature(items, count);
  for (index = 0; index < g_cloud_automation_count; index++)
    {
      const struct cloud_automation_record_s *record =
        &g_cloud_automations[index];
      unsigned int action;

      signature = (signature ^ record->routine_id) * 16777619u;
      signature = (signature ^ record->trigger_device_hash) * 16777619u;
      signature = (signature ^ record->trigger_siid) * 16777619u;
      signature = (signature ^ record->trigger_piid) * 16777619u;
      signature = (signature ^ record->minute_of_day) * 16777619u;
      signature = (signature ^ record->delay_seconds) * 16777619u;
      signature = (signature ^ record->days_mask) * 16777619u;
      for (action = 0; action < record->action_count; action++)
        {
          signature = (signature ^ record->actions[action].device_hash) *
                      16777619u;
          signature = (signature ^ record->actions[action].siid) *
                      16777619u;
          signature = (signature ^ record->actions[action].piid) *
                      16777619u;
          signature = (signature ^ (uint32_t)record->actions[action].value) *
                      16777619u;
        }
    }
  if (signature == g_proactive_automation_signature)
    {
      return;
    }

  g_proactive_automation_signature = signature;
  memset(g_proactive_automation_ui, 0,
         sizeof(g_proactive_automation_ui));
  lv_obj_clean(g_proactive_automation_list);
  if (count == 0 && g_cloud_automation_count == 0)
    {
      make_label(g_proactive_automation_list,
                 "暂无离线自动化；云端候选需经你确认后才会写入",
                 0, 8, lv_color_hex(COLOR_MUTED),
                 home_panel_font_get());
      return;
    }

  for (index = 0; index < count; index++)
    {
      const struct home_panel_device_s *device =
        proactive_find_device_hash(items[index].action_device_hash);
      lv_obj_t *row = lv_obj_create(g_proactive_automation_list);
      lv_obj_t *button;
      lv_obj_t *label;
      char text[192];

      lv_obj_set_pos(row, 0, index * 56);
      lv_obj_set_size(row, lv_pct(100), THEME_MIN_TOUCH);
      lv_obj_set_style_radius(row, THEME_RADIUS_SM, 0);
      lv_obj_set_style_bg_color(row, lv_color_hex(COLOR_SURFACE_2), 0);
      lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
      lv_obj_set_style_border_width(row, 0, 0);
      lv_obj_set_style_pad_all(row, 0, 0);
      lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

      if (items[index].event_triggered)
        {
          snprintf(text, sizeof(text), "设备联动%s%u 分钟 · %s → %s",
                   items[index].mean_delay_seconds > 0 ? " 延迟 " : "",
                   items[index].mean_delay_seconds / 60u,
                   device == NULL ? "已移除设备" : device->name,
                   items[index].action_kind == HOME_PROACTIVE_EVENT_BOOLEAN ?
                     (items[index].action_value != 0 ? "开启" : "关闭") :
                     "调整状态");
        }
      else
        {
          snprintf(text, sizeof(text), "%02u:%02u · %s → %s",
                   items[index].mean_minute_of_day / 60u,
                   items[index].mean_minute_of_day % 60u,
                   device == NULL ? "已移除设备" : device->name,
                   items[index].action_kind == HOME_PROACTIVE_EVENT_BOOLEAN ?
                     (items[index].action_value != 0 ? "开启" : "关闭") :
                     "调整状态");
        }
      label = make_label(row, text, 12, 16,
                         lv_color_hex(COLOR_SECONDARY),
                         home_panel_font_get());
      lv_obj_set_width(label, 620);
      lv_label_set_long_mode(label, LV_LABEL_LONG_DOT);

      g_proactive_automation_ui[index].routine_id =
        items[index].routine_id;
      button = make_action_button(row, "删除", 650, 0, 74);
      style_secondary_action(button);
      lv_obj_remove_event_cb(button, action_clicked);
      lv_obj_add_event_cb(button, proactive_automation_delete_clicked,
                          LV_EVENT_CLICKED,
                          &g_proactive_automation_ui[index]);
    }

  for (index = 0; index < g_cloud_automation_count; index++)
    {
      const struct cloud_automation_record_s *record =
        &g_cloud_automations[index];
      unsigned int ui_index = count + index;
      const struct home_panel_device_s *device =
        cloud_find_device(record->actions[0].device_hash);
      lv_obj_t *row = lv_obj_create(g_proactive_automation_list);
      lv_obj_t *button;
      lv_obj_t *label;
      char text[192];

      lv_obj_set_pos(row, 0, ui_index * 56);
      lv_obj_set_size(row, lv_pct(100), THEME_MIN_TOUCH);
      lv_obj_set_style_radius(row, THEME_RADIUS_SM, 0);
      lv_obj_set_style_bg_color(row, lv_color_hex(COLOR_SURFACE_2), 0);
      lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
      lv_obj_set_style_border_width(row, 0, 0);
      lv_obj_set_style_pad_all(row, 0, 0);
      lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
      if (record->trigger_kind == HOME_PANEL_CLOUD_TRIGGER_TIME)
        {
          snprintf(text, sizeof(text),
                   "云端学习 %02u:%02u · %u 个动作 · %s",
                   record->minute_of_day / 60u,
                   record->minute_of_day % 60u,
                   record->action_count,
